/* Original DOS window state and drag algebra2f066/2f16a/2efc0,
 * Position2f82a and Resize30d5a/30f1a. Platform mouse sampling is external. */
#include "windows.h"
#include "mcga_draw.h"
#include <string.h>
#define DG 0x4d2c0u
static unsigned word(const uint8_t*m,unsigned a){return m[a]|((unsigned)m[a+1]<<8);}
static int signed16(unsigned v){return (int16_t)(uint16_t)v;}
static int r(const uint8_t*m,unsigned o){return signed16(word(m,DG+o));}
static void put(uint8_t*m,unsigned a,int v){m[a]=(uint8_t)v;m[a+1]=(uint8_t)((unsigned)v>>8);}
static void w(uint8_t*m,unsigned o,int v){put(m,DG+o,v);}
static unsigned farptr(const uint8_t*m,unsigned o){return word(m,DG+o)+16u*word(m,DG+o+2);}
static int valid(const uint8_t*m,size_t n){return m&&n>=1048576u;}
static const unsigned outer[4]={0,0x2970,0x2a80,0x2a24};
static const unsigned lists[4]={0,0x29c0,0x2aa0,0x2a54};
int sim_windows_activate(uint8_t*m,size_t n,unsigned id){unsigned old;if(!valid(m,n)||id>3)return 0;if(m[DG+0x5326]==id)return 1;m[DG+0x5326]=(uint8_t)id;m[DG+0x2968+id]=1;if(id&&m[DG+0x2964]!=id){old=m[DG+0x2964];m[DG+0x2964]=(uint8_t)id;m[DG+0x2965]=(uint8_t)old;m[DG+0x2966]=(uint8_t)(6-id-old);}return 1;}
int sim_windows_close(uint8_t*m,size_t n,unsigned id){if(!valid(m,n)||id<1||id>3)return 0;if(id==1)w(m,0x320c,-1);if(m[DG+0x2968+id]){m[DG+0x2968+id]=0;if(m[DG+0x2964]==id){m[DG+0x2964]=m[DG+0x2965];m[DG+0x2965]=m[DG+0x2966];m[DG+0x2966]=(uint8_t)id;m[DG+0x5326]=m[DG+0x2964];if(!m[DG+0x2968+m[DG+0x5326]])m[DG+0x5326]=0;}}return 1;}
int sim_windows_hide(uint8_t*m,size_t n){unsigned i,id;if(!valid(m,n))return 0;id=m[DG+0x5326];if(!id)return 1;if(id>3)return 0;for(i=1;i<3;++i){unsigned next=m[DG+0x2964+i];if(next>3)return 0;if(!m[DG+0x2968+next])break;if(i>=3)break;m[DG+0x2963+i]=(uint8_t)next;}if(i>1){m[DG+0x2963+i]=(uint8_t)id;m[DG+0x5326]=m[DG+0x2964];}return 1;}
int sim_windows_close_current(uint8_t*m,size_t n){unsigned id;if(!valid(m,n))return 0;id=m[DG+0x5326];if(!id)return 1;if(id==1&&m[DG+0x32f2])return sim_windows_hide(m,n);return sim_windows_close(m,n,id);}
int sim_window_rectangle(const uint8_t*m,size_t n,unsigned id,unsigned part,SimWindowRect*q){static const unsigned caption[4]={0,0x2978,0x2a70,0x2a2c},close[4]={0,0x2980,0x2a78,0x2a34};unsigned o;if(!valid(m,n)||id<1||id>3||part>2||!q)return 0;o=part==0?outer[id]:part==1?caption[id]:close[id];q->top=r(m,o);q->left=r(m,o+2);q->bottom=r(m,o+4);q->right=r(m,o+6);return 1;}
int sim_windows_draw_order(const uint8_t*m,size_t n,unsigned out[3]){int i,count=0;if(!valid(m,n)||!out)return 0;for(i=2;i>=0;--i){unsigned id=m[DG+0x2964+(unsigned)i];if(id>=1&&id<=3&&m[DG+0x2968+id])out[count++]=id;}return count;}
int sim_windows_hit(const uint8_t*m,size_t n,int x,int y){unsigned i;if(!valid(m,n))return 0;for(i=0;i<3;++i){unsigned id=m[DG+0x2964+i];SimWindowRect q;if(id>=1&&id<=3&&m[DG+0x2968+id]&&sim_window_rectangle(m,n,id,0,&q)&&x>=q.left&&x<=q.right&&y>=q.top&&y<=q.bottom)return (int)id;}return 0;}
int sim_window_drag_begin(uint8_t*m,size_t n,unsigned mode,int x,int y,SimWindowDrag*d){unsigned id;if(!valid(m,n)||!d||mode>1)return 0;if(mode==SIM_WINDOW_RESIZE){if(!sim_windows_activate(m,n,1))return 0;}id=m[DG+0x5326];if(id<1||id>3)return 0;memset(d,0,sizeof(*d));d->mode=(int)mode;d->window=(int)id;d->start_x=signed16((unsigned)x);d->start_y=signed16((unsigned)y);d->last_x=d->last_y=-1;if(!sim_window_rectangle(m,n,id,0,&d->original))return 0;d->preview=d->original;return 1;}
int sim_window_drag_update(const uint8_t*m,size_t n,int x,int y,SimWindowDrag*d){int sx,sy,v,delta,guard,tile,hmin;unsigned bits;SimWindowRect q;if(!valid(m,n)||!d||d->window<1||d->window>3)return 0;sx=signed16((unsigned)x&65528u);sy=signed16((unsigned)y&65534u);if(sx==d->last_x&&sy==d->last_y)return 1;d->last_x=sx;d->last_y=sy;q=d->original;if(d->mode==SIM_WINDOW_POSITION){bits=((unsigned)(sy-d->start_y+8))&65520u;guard=0;do{v=signed16((unsigned)d->original.top+bits);bits=(bits+16u)&65535u;if(++guard>8192)return 0;}while(v<=(int8_t)m[DG+0x120]);do{bits=(bits-16u)&65535u;q.top=signed16((unsigned)d->original.top+bits);q.bottom=signed16((unsigned)d->original.bottom+bits);if(++guard>16384)return 0;}while(q.bottom>r(m,0x15ca));bits=((unsigned)(sx-d->start_x+8))&65520u;guard=0;do{v=signed16((unsigned)d->original.left+bits);bits=(bits+16u)&65535u;if(++guard>8192)return 0;}while(v<0);bits=(bits+16u)&65535u;do{bits=(bits-16u)&65535u;q.left=signed16((unsigned)d->original.left+bits);q.right=signed16((unsigned)d->original.right+bits);if(++guard>16384)return 0;}while(q.right>r(m,0x15cc));}
 else if(d->mode==SIM_WINDOW_RESIZE){tile=r(m,0x2b1e);hmin=r(m,0x2a22);if(tile<=0)return 0;delta=signed16((unsigned)(sy-d->start_y))/tile*tile;guard=0;for(;;){q.bottom=signed16((unsigned)(d->original.bottom+delta));while(signed16((unsigned)(q.bottom-q.top))<hmin){delta=signed16((unsigned)(delta+tile));q.bottom=signed16((unsigned)(d->original.bottom+delta));if(++guard>8192)return 0;}if(q.bottom<r(m,0xf8))break;delta=signed16((unsigned)(delta-tile));if(++guard>16384)return 0;}tile=r(m,0x2b1c);hmin=r(m,0x2a20);if(tile<=0)return 0;delta=signed16((unsigned)(sx-d->start_x))/tile*tile;guard=0;for(;;){q.right=signed16((unsigned)(d->original.right+delta));while(signed16((unsigned)(q.right-q.left))<hmin){delta=signed16((unsigned)(delta+tile));q.right=signed16((unsigned)(d->original.right+delta));if(++guard>8192)return 0;}if(q.right<r(m,0xf6))break;delta=signed16((unsigned)(delta-tile));if(++guard>16384)return 0;}}
 else {return 0;}d->preview=q;d->dx=q.right-d->original.right;d->dy=q.bottom-d->original.bottom;return 1;}
static int change_list(uint8_t*m,unsigned list,int dx,int dy,int mode){unsigned i,a,o;for(i=0;i<64;++i){o=list+i*4;a=farptr(m,o);if(!a)return 1;if(a+8>1048576u)return 0;if(mode==0){put(m,a,signed16(word(m,a)+(unsigned)dy));put(m,a+2,signed16(word(m,a+2)+(unsigned)dx));put(m,a+4,signed16(word(m,a+4)+(unsigned)dy));put(m,a+6,signed16(word(m,a+6)+(unsigned)dx));}else if(mode==1)put(m,a+6,signed16(word(m,a+6)+(unsigned)dx));else put(m,a+4,signed16(word(m,a+4)+(unsigned)dy));}return 0;}
int sim_window_drag_commit(uint8_t*m,size_t n,const SimWindowDrag*d){int cols,rows;if(!valid(m,n)||!d||d->window<1||d->window>3)return 0;if(d->mode==SIM_WINDOW_POSITION)return change_list(m,lists[d->window],d->dx,d->dy,0);if(d->mode!=SIM_WINDOW_RESIZE||d->window!=1||r(m,0x2b1e)<=0||r(m,0x2b1c)<=0)return 0;if(!change_list(m,0x29ec,d->dx,d->dy,1)||!change_list(m,0x2a08,d->dx,d->dy,2))return 0;w(m,0x29a8,r(m,0x29a8)+d->dy);w(m,0x29b0,r(m,0x29b0)+d->dy);w(m,0x29b2,r(m,0x29b2)+d->dx);rows=signed16((unsigned)(r(m,0x2994)-r(m,0x2990)))/r(m,0x2b1e)+1;cols=signed16((unsigned)(r(m,0x2996)-r(m,0x2992)))/r(m,0x2b1c)+1;w(m,0x296c,rows);w(m,0x296e,cols);if(cols+r(m,0x5f10)>120)w(m,0x5f10,120-cols);if(rows+r(m,0x5f0e)>100)w(m,0x5f0e,100-rows);return 1;}


int sim_window_preview_render(uint8_t*fb,const SimWindowDrag*d){int x0,y0,x1,y1;if(!fb||!d)return 0;x0=d->preview.left;y0=d->preview.top;x1=d->preview.right;y1=d->preview.bottom;return sim_mcga_fill(fb,x0,y0+2,x0+1,y1-2,255,SIM_MCGA_XOR)&&sim_mcga_fill(fb,x1-1,y0+2,x1,y1-2,255,SIM_MCGA_XOR)&&sim_mcga_fill(fb,x0,y0,x1,y0+1,255,SIM_MCGA_XOR)&&sim_mcga_fill(fb,x0,y1-1,x1,y1,255,SIM_MCGA_XOR);}
